/* Portable source pack for engines with an integration point. It is exported,
 * never injected into an arbitrary compiled ROM. */
const esc=s=>String(s).replace(/[^ -~]/g,c=>'\\'+c.charCodeAt(0).toString(8).padStart(3,'0')).replace(/[\\"]/g,'\\$&');
export const UI_ENGINE_HEADER=`#pragma once\n#include <stdint.h>\ntypedef struct { uint16_t id,x,y,w,h,fill,stroke,value,max; uint8_t type,font,visible; const char *text,*binding; } PBUIElement;\ntypedef struct { const PBUIElement *elements; uint16_t count; } PBUIScreen;\ntypedef struct { void(*rect)(int,int,int,int,uint16_t,uint16_t); void(*text)(int,int,const char*,uint16_t); void(*image)(int,int,int); uint16_t(*resolve)(const char*); } PBUIEngine;\nvoid PBUI_Draw(const PBUIEngine*,const PBUIScreen*); int PBUI_Hit(const PBUIScreen*,int,int);\n`;
export const UI_ENGINE_C=`#include "pokebacon_ui.h"\nvoid PBUI_Draw(const PBUIEngine*e,const PBUIScreen*s){for(int i=0;i<s->count;i++){const PBUIElement*x=&s->elements[i];if(!x->visible)continue;if(x->type==0||x->type==3)e->rect(x->x,x->y,x->w,x->h,x->fill,x->stroke);if(x->type==1&&e->text)e->text(x->x,x->y,x->text,x->fill);if(x->type==2&&e->rect){uint16_t v=x->binding&&e->resolve?e->resolve(x->binding):x->value,m=x->max?x->max:1;if(v>m)v=m;e->rect(x->x,x->y,x->w*v/m,x->h,x->fill,x->stroke);}if(x->type==4&&e->image)e->image(x->x,x->y,x->id);}}\nint PBUI_Hit(const PBUIScreen*s,int x,int y){for(int i=s->count-1;i>=0;i--){const PBUIElement*e=&s->elements[i];if(e->visible&&e->type==3&&x>=e->x&&y>=e->y&&x<e->x+e->w&&y<e->y+e->h)return e->id;}return -1;}\n`;
export function uiEngineSource(theme){const screens=theme.screens.map(s=>`static const PBUIElement ${s.id}[] = {${s.elements.map((e,i)=>`{${i},${e.x},${e.y},${e.width},${e.height},0,0,${e.value||0},${e.max||1},${({window:0,text:1,bar:2,button:3,image:4}[e.type]??0)},${e.font||10},${e.visible===false?0:1},"${esc(e.text||'')}","${esc(e.binding||'')}"}`).join(',')}};`).join('\n');return [['pokebacon_ui.h',UI_ENGINE_HEADER],['pokebacon_ui.c',UI_ENGINE_C],['pokebacon_theme.c',screens+'\n/* Wire these screen arrays to your engine’s renderer callbacks. */\n'],['theme.json',JSON.stringify(theme,null,2)],['README.txt','Generated portable C source. Supply the engine-specific draw/font/image callbacks; PokéBacon does not guess offsets in a compiled ROM.\n']];}
